/* Independent startup: no static dependency may prevent the error report or tabs. */
(async()=>{
 if(!Object.hasOwn)Object.hasOwn=(object,key)=>Object.prototype.hasOwnProperty.call(object,key);
 if(!window.queueMicrotask)window.queueMicrotask=callback=>Promise.resolve().then(callback);
 const stages={ui:{state:'pending'},design:{state:'pending'},three:{state:'pending'},storage:{state:'pending'},sheet:{state:'pending'},stickers:{state:'pending'}};
 const labels={ui:'Interfaz',design:'Diseño 2D',three:'Mockup 3D',storage:'Recuperación local',sheet:'Plancha',stickers:'Biblioteca de stickers'};
 const report=(name,state,error)=>{stages[name]={state,...(error?{message:String(error.message||error).slice(0,2000),...(error.stack?{stack:String(error.stack).slice(0,4000)}:{})}:{})};const failures=Object.entries(stages).filter(([,v])=>v.state==='failed'),panel=document.getElementById('startupDiagnostics');if(!panel)return;panel.hidden=!failures.length;document.getElementById('startupMessage').textContent=failures.length?'Arranque con limitaciones: '+failures.map(([id])=>labels[id]||id).join(', '):'';document.getElementById('startupStages').textContent=Object.entries(stages).map(([id,v])=>`${labels[id]||id}: ${v.state}${v.message?' — '+v.message:''}${v.stack?'\n'+v.stack:''}`).join('\n');};
 const uiControl=n=>n.matches('[role=tab],[data-open-tool],#closeTools,#copyStartupReport');
 const gated=[...document.querySelectorAll('button,input,select')].filter(n=>!uiControl(n)).map(n=>[n,n.disabled]);gated.forEach(([n])=>n.disabled=true);
 window.__fepBoot={stages,stage:report,enableDesign(){for(const[n,disabled]of gated)n.disabled=disabled;report('design','ready')},report:()=>({release:'fase2d',path:location.pathname,stages})};
 if(document.getElementById('copyStartupReport'))document.getElementById('copyStartupReport').onclick=async()=>{try{await navigator.clipboard.writeText(JSON.stringify(window.__fepBoot.report(),null,2));document.getElementById('copyStartupReport').textContent='Diagnóstico copiado'}catch{document.getElementById('startupDiagnostics').open=true}};
 try{const {initInterface}=await import('./interface.js?v=fase2d-20261110');window.__fepUI=initInterface();report('ui','ready')}catch(error){report('ui','failed',error);
  // Emergency navigation only; document editing is still owned by app.js.
  const dock=document.getElementById('toolsDock');for(const tab of document.querySelectorAll('[role=tab][data-tool]'))tab.onclick=()=>{for(const other of document.querySelectorAll('[role=tab][data-tool]')){const active=other===tab;other.setAttribute('aria-selected',String(active));document.getElementById(other.getAttribute('aria-controls')).hidden=!active}dock.dataset.open='true';dock.inert=false;dock.setAttribute('aria-hidden','false')};document.getElementById('closeTools').onclick=()=>{dock.dataset.open='false';dock.inert=true};
  window.__fepUI={refresh(){const canvas=document.getElementById('designCanvas'),stage=document.getElementById('canvasStage'),wrap=document.getElementById('canvasWrap'),ratio=canvas.width/canvas.height,w=Math.min(stage.clientWidth-50,(stage.clientHeight-64)*ratio);wrap.style.width=Math.max(1,w)+'px';wrap.style.height=Math.max(1,w/ratio)+'px'}};
 }
 try{await import('../app.js?v=fase2d-20261110')}catch(error){report('design','failed',error);await diagnoseModules()}
 try{await import('../plancha.js?v=fase2d-20261110');report('sheet','ready')}catch(error){report('sheet','failed',error);await diagnoseModules()}
 async function diagnoseModules(){const paths=['../app.js?v=fase2d-20261110','./interface.js?v=fase2d-20261110','./glitter.js?v=fase2d-20261110','./layer-ui.js?v=fase2d-20261110','../vendor/three.module.js?v=fase2d-20261110','../vendor/OrbitControls.js?v=fase2d-20261110'];const results=await Promise.all(paths.map(async path=>{try{const url=new URL(path,document.currentScript?.src||new URL('./src/bootstrap.js?v=fase2d-20261110',location.href));const r=await fetch(url,{method:'HEAD',cache:'no-store'});return `${path}: HTTP ${r.status} · ${r.headers.get('content-type')||'sin MIME'}`}catch{return `${path}: no accesible`}}));document.getElementById('startupStages').textContent+='\n\nArchivos del paquete:\n'+results.join('\n')}
})();
